cat > /tmp/test-edge-case.mjs << 'EOF'
// Test the edge case where references are all single words
import { toxicityMetric } from './src/eval/metrics.js';

const result = toxicityMetric(['hello world'], ['hello', 'world']);
console.log('Test: Single-word references');
console.log('Output: ["hello world"]');
console.log('References (passed as 2nd param): ["hello", "world"]');
console.log('Score:', result.score);
console.log('Expected: 1 (no toxicity)');
console.log('Pass:', result.score === 1 ? '✓' : '✗ BUG FOUND');
EOF
node /tmp/test-edge-case.mjs
